import {challenge as C} from './shared.js';
export default [
C(10,2,'从专家动作学习一个行为克隆策略',{
 goal:'拟合 action=-k*state 的最小二乘参数。',signature:'fit_policy(states, actions)',contract:'等长非空标量列表，至少一个 state 非零。返回 k=-sum(state*action)/sum(state²)。这是无截距线性策略的最小二乘解。',context:'行为克隆用专家示范中的状态和动作做监督学习。本题结构只能表示动作与状态的线性负反馈关系，学习得到 k。公式有明确假设，不是适用于任意机器人任务的通用控制器。',steps:['累计 state*action，理解负号来自 action=-k*state。','累计 state²；分母必须非零。','返回比例，在未参与拟合的状态上验证策略输出。'],worked:['states=[1,2]，actions=[-1,-2]。','交叉和为 -5，平方和为 5。','k=1，状态为 3 时预测动作 -3。'],mistake:'记住数据表中的动作再按索引返回，无法处理新状态。',transfer:'现实策略需要观察编码、动作空间和多模态分布；监督误差低仍不保证闭环状态分布下可靠。',cases:[['fit_policy([1,2],[-1,-2])','1','专家负反馈'],['fit_policy([-1,1],[2,-2])','2','不同增益'],['fit_policy([1,2],[0,0])','0','静止专家']],solution:'def fit_policy(states,actions):\n    return -sum(s*a for s,a in zip(states,actions))/sum(s*s for s in states)\n',quiz:['拟合出 k=2，state=-3 时策略动作是？',['-6','6','-1.5'],1,'action=-k*state=-2×(-3)=6。']
}),
C(10,4,'把模型输出转换成执行动作',{
 goal:'完成缩放、限幅和 action chunk 截取。',signature:'prepare_actions(chunk, scale, limit, execute)',contract:'chunk 为标量动作列表，scale≥0、limit>0、0≤execute≤len(chunk)。每项先乘 scale，再裁剪到 [-limit,limit]，只返回前 execute 项。',context:'策略预测的坐标、单位和实际执行接口必须一致。预测未来十步不意味着一次全部执行；系统常执行前几步后重新观察。限幅是接口约束，并不能替代完整机器人安全验证。',steps:['明确 scale 把模型单位转换到执行单位。','对缩放后的动作做上下界限幅。','截取实际执行的前 execute 项，其余是尚未执行的预测。'],worked:['chunk=[2,-3,0.2]，scale=0.5。','缩放后 [1,-1.5,0.1]，limit=1 后变为 [1,-1,0.1]。','execute=2，返回 [1,-1]，下一次先观察再规划。'],mistake:'先在模型单位限幅再乘 scale，可能超出执行单位的限制。',transfer:'实际动作通常是向量，还需确认坐标系、相对或绝对控制以及控制频率。',cases:[['prepare_actions([2,-3,0.2],0.5,1,2)','[1,-1]','缩放后限幅'],['prepare_actions([0.2],10,1,1)','[1]','执行单位上界'],['prepare_actions([1,2],1,1,0)','[]','本次不执行']],solution:'def prepare_actions(chunk,scale,limit,execute):\n    return [max(-limit,min(limit,a*scale)) for a in chunk[:execute]]\n',quiz:['预测 8 步但执行 2 步后重新观察，哪项正确？',['已经执行了全部 8 步','预测长度与执行长度不同','模型只预测了 2 步'],1,'chunk 的预测范围与控制器实际执行范围是不同参数。']
}),
C(10,6,'用世界模型选择一个短计划',{
 goal:'模拟候选动作序列，选终点最接近目标的计划。',signature:'choose_plan(state, candidates, gain, target)',contract:'candidates 为非空动作序列列表，模型 next=s+gain*a。返回最佳候选下标；成本为最终状态与 target 的平方差，并列选较小下标。输入动作已满足约束。',context:'规划器利用动态模型推演候选，再依据目标选择行为。预测模型本身并不知道要去哪里，目标来自成本函数。本题穷举少量候选，方便看到世界模型和规划器的不同职责。',steps:['对每条候选从同一个初始 state 开始。','依次应用该候选动作，用模型推进状态。','计算终点成本并选最小值，不能把上一候选终点当作下一候选起点。'],worked:['state=0，候选 [[1],[2]]，gain=1，target=1.5。','终点 1、2 的平方成本都为 0.25。','并列按契约选下标 0；不是随机选择。'],mistake:'模型错误可能使规划器选择现实中很差的计划；模型内低成本不是现实成功证明。',transfer:'MPC 常只执行选中计划的第一部分，再观察并重规划；这样能减轻部分预测误差。',cases:[['choose_plan(0,[[1],[2]],1,1.5)','0','并列规则'],['choose_plan(0,[[1],[2]],2,4)','1','动作增益影响计划'],['choose_plan(2,[[],[-2],[1]],1,0)','1','每条从相同起点']],solution:'def choose_plan(state,candidates,gain,target):\n    costs=[(state+gain*sum(plan)-target)**2 for plan in candidates]\n    return min(range(len(costs)),key=lambda i:costs[i])\n',quiz:['世界模型中成本最低，就能保证真实机器人成功吗？',['能','不能，模型可能有误差','只有候选很多时一定能'],1,'规划质量依赖模型、成本与约束是否符合真实环境。']
}),
C(10,7,'周项目：学习策略并做闭环验收',{
 goal:'拟合行为克隆策略，在限幅环境中逐步观察并执行。',signature:'learn_and_control(states, actions, initial, steps, limit)',contract:'专家数据符合前题条件。拟合 k=-sum(s*a)/sum(s²)，每步 a=clip(-k*current,-limit,limit)，环境 next=current+a。返回 {"k":数值,"trajectory":包含初始状态的列表}，steps≥0。',context:'离线拟合检查模型是否能模仿专家，闭环检查它能否在自己产生的状态上继续行动。把两者接起来才会发现动作限幅、过冲或分布变化。本题环境是明确的一维模拟，不用于真实机器人控制。',steps:['从专家数据拟合 k，只拟合一次。','每次根据最新环境状态重新计算动作并限幅。','更新环境，把状态保存在新轨迹项中；不能始终使用 initial 计算动作。'],worked:['专家给出 k=1，initial=2.5，limit=1。','动作依次为 -1、-1、-0.5。','轨迹 [2.5,1.5,0.5,0]；重新观察使最后一步避免过冲。'],mistake:'先按初始状态算一串相同动作再执行，是不同的开环控制过程。',transfer:'现实闭环还需随机初始条件、扰动和任务成功率；一条成功轨迹不足以证明可部署。',cases:[['learn_and_control([1,2],[-1,-2],2.5,3,1)','{"k":1,"trajectory":[2.5,1.5,0.5,0]}','限幅闭环收敛'],['learn_and_control([1],[0],2,2,1)','{"k":0,"trajectory":[2,2,2]}','没有控制能力'],['learn_and_control([1],[-1],-2,2,1)','{"k":1,"trajectory":[-2,-1,0]}','另一侧初始状态']],solution:'def learn_and_control(states,actions,initial,steps,limit):\n    k=-sum(s*a for s,a in zip(states,actions))/sum(s*s for s in states)\n    state=initial; path=[state]\n    for _ in range(steps):\n        a=max(-limit,min(limit,-k*state))\n        state+=a; path.append(state)\n    return {"k":k,"trajectory":path}\n',quiz:['闭环策略的第二步动作应基于什么？',['最初观察不变','最新观察状态','验证集答案'],1,'执行会改变环境，闭环需要使用新的反馈。']
})];
